/* wardrobe.mjs — what the mascot can wear, and the item shop that sells it (study kit; founder 2026-10-24: "a much more
   fleshed out accessory system with several Fortnite inspired items, durag and diverse accessories ... make the game
   store more like other video game stores").

   The catalogue: every item has a slot the dog page draws (public/doberman/: wearHead, wearFace, wearNeck, wearBack), a
   rarity and a price inside that rarity's band, a pop-culture nod (a description, never a name or a logo), and its
   SVG in the dog's head units (head 100 wide, centred on x 1, its top edge at y -55, where every hat sits; glasses on
   the eye line, y -31; neckwear on the collar band, y 0; back bling in the body's own frame, behind the body, so wings,
   packs and capes peek out round a head-first three-quarter dog). Drawn in the dogs' flat style: one base, one shade,
   one highlight. vb frames the shop tile when the slot's default would crop the piece; tile crops it for the shop only,
   and bleed marks a tall piece whose tile shows its top and lets the rest sink behind the name plate (the fit audit
   holds every other piece to one visual size in its tile). A glasses arm or strap goes in
   <g data-arm="">: the dog page clips it to the head's outline, so it tucks behind the head on every dog (a narrow
   Pinscher face or a round Pomeranian one) instead of sticking out into the air past it. Fabric on a back piece is
   drawn on the doberman's body and fitted to each dog's from its rump (public/doberman/parts.mjs drape): what lies on
   the body goes in <g data-on=""> (drawn over the coat, trimmed to the body's outline: a cape's near side), what hangs
   from the rump in <g data-rump=""> (a cape's free end, ending as far off the floor on every build). A piece worn that
   way has an icon, its shop drawing. The dog page fits three more kinds of part to each build (stage.mjs fitNeck,
   fitBack): what hangs from a neck piece goes in <g data-hang=""> (a scarf's end, a stole's two: shortened to end off the
   floor of a corgi or a dachshund; a piece that still reaches the floor is drawn smaller); a pack drawn with its foot
   inside the doberman's rump goes in <g data-pack=""> (moved onto a shorter dog's rump, so it never hangs past it); what
   stands beside the head goes in <g data-side=""> (a jetpack's tanks: moved out to a mane's or a hanging ear's edge). A
   fitted group carries no transform of its own (the page sets it) and lies in the piece's frame, at most mirrored by MIR. A hat's base meets the head's top line (y -55) or comes below it: a base a unit above it showed the
   page as a hairline (the fit audit's seam check).

   The shop is Fortnite's item shop, read as a design (rarity tiers coloured grey, green, blue, purple, gold; a daily
   rotation that resets at midnight with a countdown; a featured bundle priced for the parts you do not own yet; one
   daily deal), with Duolingo's rule that the currency only comes from study. shopFor(day) is pure and seeded by the
   date, so every device shows the same shop on the same day. Everything here is pure (scripts/mascot.test.js). */

export const SLOTS = ['head', 'face', 'neck', 'back'];
export const SLOT_NAME = { head: 'Hats', face: 'Glasses', neck: 'Neckwear', back: 'Back bling' };
export const RARITY = {
  common: { name: 'Common', min: 10, max: 15 },
  uncommon: { name: 'Uncommon', min: 20, max: 25 },
  rare: { name: 'Rare', min: 30, max: 40 },
  epic: { name: 'Epic', min: 50, max: 65 },
  legendary: { name: 'Legendary', min: 80, max: 120 },
  exclusive: { name: 'Exclusive', min: 0, max: 0 }
};
export const RARITIES = Object.keys(RARITY);
const NEW = '2026-10-24', NEW6 = '2026-10-25', NEW7 = '2026-10-26', NEW8 = '2026-10-29';
/* the same drawing on the other side of the head's centre line (x 1) */
const MIR = s => `${s}<g transform="matrix(-1 0 0 1 2 0)">${s}</g>`;
/* a contact shadow under a hat's base, in the dog's own shade (the dog page sets --dob-sh on each dog; a shop tile has
   none, so it draws nothing there): the hat sits on the head instead of being painted over it */
const SHADE = (w, y = -55, d = 3.6) => `<path d="M${1 - w} ${y} Q1 ${y + 2 * d} ${1 + w} ${y} Q1 ${y + d} ${1 - w} ${y} Z" style="fill:var(--dob-sh,none)"/>`;
/* a satin durag: the dome, a seam, the front band, and the tail and a tie hanging behind on the far side. The tail is
   the satin's shade unless it asks for its own (t): a gold one hangs in deep bronze under its light tie, so the pair reads
   on a golden or cream dog as well as a dark one (in the shade's gold it matched a golden retriever's ear, 1.1 : 1) */
const DURAG = (c, s, b, k, h, t = s) => `<path d="M-44 -60 C-58 -52 -63 -30 -59 -4 C-58 3 -50 5 -48 -1 C-51 -22 -49 -42 -38 -56 Z" fill="${t}"/><path d="M-46 -52 C-56 -42 -60 -26 -62 -12" fill="none" stroke="${c}" stroke-width="5" stroke-linecap="round"/><path d="M-48 -48 C-50 -80 -24 -89 1 -89 C26 -89 52 -80 50 -48 C34 -57 -32 -57 -48 -48 Z" fill="${c}"/><path d="M1 -89 C26 -89 52 -80 50 -48 C42 -52 30 -55 18 -56 C21 -68 15 -81 1 -89 Z" fill="${s}"/><path d="M1 -88 Q-1 -72 1 -57" fill="none" stroke="${k}" stroke-width="1.6" stroke-linecap="round"/><path d="M-48 -49 C-32 -59 34 -59 50 -49 L50 -45 C34 -54 -32 -54 -48 -45 Z" fill="${b}"/><path d="M-34 -62 Q-30 -78 -12 -84" fill="none" stroke="${h}" stroke-width="3.6" stroke-linecap="round"/><path d="M-16 -68 Q-12 -74 -6 -76" fill="none" stroke="${h}" stroke-width="2.4" stroke-linecap="round"/>`;
/* each slot's frame for a piece's art in the shop (an item's vb overrides it; tile crops a tall piece for its tile) */
export const VB = { head: '-56 -126 112 80', face: '-54 -50 108 38', neck: '-42 -10 84 46', back: '-96 -96 192 120' };
const flower = (x, y, c) => `<g transform="translate(${x} ${y})">${[0, 72, 144, 216, 288].map(a => `<circle cx="${(Math.cos(a * Math.PI / 180) * 3.6).toFixed(2)}" cy="${(Math.sin(a * Math.PI / 180) * 3.6).toFixed(2)}" r="3.4" fill="${c}"/>`).join('')}<circle r="2" fill="#ffe36b"/></g>`;
/* a clown ruff's pleats: lobes along the collar band, alternating colours */
const RUFF = Array.from({ length: 11 }, (_, i) => { const t = i / 10, x = (1 - t) ** 2 * -34 + 2 * t * (1 - t) + t * t * 36, y = (1 - t) ** 2 * -3 + 2 * t * (1 - t) * 15 + t * t * -3; return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="6.4" fill="${i % 2 ? '#ffd23f' : '#ff5fa2'}"/>`; }).join('');
const LEI = [[-33, -1], [-24, 6], [-13, 11], [1, 13], [15, 11], [26, 6], [35, -1]].map(([x, y], i) => flower(x, y, ['#ff5fa2', '#ffb02e', '#b06bff', '#ff7a3d'][i % 4])).join('');
/* a feather boa's puffs: lobes along the collar band, two pinks, a lighter catch on every other one */
const BOA = Array.from({ length: 11 }, (_, i) => { const t = i / 10, x = (1 - t) ** 2 * -34 + 2 * t * (1 - t) + t * t * 36, y = (1 - t) ** 2 * -3 + 2 * t * (1 - t) * 15 + t * t * -3; return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="6" fill="${i % 2 ? '#ff8cc0' : '#ff5fa2'}"/>` + (i % 2 ? '' : `<circle cx="${(x - 1.8).toFixed(1)}" cy="${(y - 1.8).toFixed(1)}" r="1.8" fill="#ffd1e5"/>`); }).join('');
