export const itemOf = id => ITEMS.find(i => i.id === id) || null;

/* the outfit as the dog page's message: one SVG string per slot ('' takes the slot off) */
export const wearMsg = (w, fresh) => ({ dob: 'wear', fresh: !!fresh, ...Object.fromEntries(SLOTS.map(s => [s, itemOf(w?.[s])?.svg || ''])), ears: itemOf(w?.head)?.ears || '', lens: itemOf(w?.face)?.lens || '', aura: auraOf(w) });
/* signature moves (public/doberman/moves.mjs): a piece's own move, the moves a look can do (head, face, neck, back), and
   the one aura it keeps up (the first legendary piece that has one); ids only, the dog page looks them up */
export const sigOf = id => itemOf(id)?.sig || null;
export const movesOf = w => SLOTS.map(s => sigOf(w?.[s])?.move).filter(Boolean);
export const auraOf = w => SLOTS.map(s => sigOf(w?.[s])?.aura).find(Boolean) || '';

