export const SET_OFF = 0.25, DEAL_OFF = 0.4, NEW_DAYS = 14;
const seed = s => { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const rng = s => { let a = seed(s); return () => { a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };
const shuffle = (rnd, list) => { const a = list.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const round5 = n => Math.max(5, Math.round(n / 5) * 5);
const daysBetween = (a, b) => Math.round((Date.parse(`${b}T12:00:00`) - Date.parse(`${a}T12:00:00`)) / 864e5);

/* today's shop: a featured bundle, two featured epic-or-better pieces, six daily pieces, and the dearest daily piece on
   a deal. Seeded by the date: the same shop on every device all day, a new one at midnight */
export function shopFor(day) {
  const rnd = rng(`shop:${day}`), set = SETS[Math.floor(rnd() * SETS.length)];
  const pool = ITEMS.filter(i => !i.exclusive && !set.items.includes(i.id));
  const featured = shuffle(rnd, pool.filter(i => i.rarity === 'legendary' || i.rarity === 'epic')).slice(0, 2);
  const daily = shuffle(rnd, pool.filter(i => !featured.includes(i))).slice(0, 6);
  const deal = daily.reduce((a, b) => (b.price > a.price ? b : a));
  return { day, set: set.id, featured: featured.map(i => i.id), daily: daily.map(i => i.id), deal: deal.id };
}
/* what one piece costs today: its price, or the deal's */
export function priceToday(id, day) {
  const it = itemOf(id); if (!it) return 0;
  return shopFor(day).deal === id ? round5(it.price * (1 - DEAL_OFF)) : it.price;
}
/* a bundle: the full price of the parts you lack, and what the bundle asks for them (0 when you own them all) */
export function setPrice(id, owned = []) {
  const s = SETS.find(x => x.id === id); if (!s) return { full: 0, price: 0, left: [] };
  const left = s.items.filter(i => !owned.includes(i)), full = left.reduce((n, i) => n + (itemOf(i)?.price || 0), 0);
  return { full, price: left.length ? round5(full * (1 - SET_OFF)) : 0, left };
}
export const isNew = (it, day) => !!it?.added && daysBetween(it.added, day) >= 0 && daysBetween(it.added, day) < NEW_DAYS;
/* until the shop turns over (local midnight) */
export function msToReset(now = Date.now()) { const d = new Date(now); d.setHours(24, 0, 0, 0); return d.getTime() - now; }
export function resetLabel(ms) { const m = Math.max(1, Math.ceil(ms / 60000)), h = Math.floor(m / 60); return h ? `${h}h ${String(m % 60).padStart(2, '0')}m` : `${m}m`; }
